#!/usr/bin/env bash
# Build and publish the web client (apps/web) to the VPS static host.
#
# Caddy serves /srv/demli-app read-only at https://app.<DOMAIN> (SPA
# fallback to index.html; see the app.{$DOMAIN} block in Caddyfile). A
# "release" is the
# whole Vite dist/ tree: index.html + content-hashed /assets/* + the PWA files
# (site.webmanifest, favicon.ico, favicon.svg, favicon-*.png, icon-*.png,
# maskable-icon-*.png, apple-touch-icon.png — all generated by pnpm gen:icons).
#
# Files are uploaded IN PLACE into the bind-mounted dir (Docker bind mounts track
# the directory inode, so a mv-swap would NOT update what Caddy serves). Old
# hashed /assets/* are intentionally left behind so a client still holding the
# previous index.html can fetch its chunks during rollout; prune them manually if
# they ever accumulate.
#
# Credentials are NOT baked in — you supply the SSH target. Auth is auto-detected:
#   - PuTTY `pscp`/`plink` (Windows Git Bash) when DEPLOY_PASS is set, else
#   - `sshpass` scp/ssh (Linux/WSL) when DEPLOY_PASS is set, else
#   - an SSH key/agent (omit DEPLOY_PASS).
#
# Usage (from repo root):
#   bash scripts/publish-web.sh                                        # key/agent
#   DEPLOY_PASS='...' bash scripts/publish-web.sh
#   SKIP_BUILD=1 bash scripts/publish-web.sh   # reuse an existing apps/web/dist
#
# The build's API/WS/LiveKit origins are baked in at build time (Vite inlines
# VITE_*). They MUST match the CSP connect-src in Caddyfile — both derive from
# the same DOMAIN, so keep DEMLI_DOMAIN consistent with the server's DOMAIN.
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

# Load machine-local deploy credentials if present (.env.deploy is gitignored),
# so this runs as a bare `bash scripts/publish-web.sh` with no secret on the
# command line. Explicit env vars still win.
if [[ -f "$REPO_ROOT/.env.deploy" ]]; then
  set -a
  # shellcheck disable=SC1091
  . "$REPO_ROOT/.env.deploy"
  set +a
fi

# Host-key pinning + password-off-argv for every auth branch (security-review
# HIGH x2). Verifies the pinned DEPLOY_HOSTKEY on the OpenSSH path too, which
# `-o StrictHostKeyChecking=accept-new` did not.
# shellcheck source=lib/remote-ssh.sh
. "$REPO_ROOT/scripts/lib/remote-ssh.sh"

DOMAIN="${DEMLI_DOMAIN:-getdemli.com}"
DIST_DIR="$REPO_ROOT/apps/web/dist"
REMOTE_DIR="/srv/demli-app"
# VPS SSH host-key fingerprint, so batch (non-interactive) auth never prompts.
# REQUIRED, from the gitignored .env.deploy — deliberately not baked in, so this
# repo can go public without publishing the server identity. Read it once with:
#   ssh-keyscan -t ed25519 HOST | ssh-keygen -lf -   (or PuTTY on first connect)
: "${DEPLOY_HOSTKEY:?Set DEPLOY_HOSTKEY (the VPS SSH host-key fingerprint) in .env.deploy}"

: "${DEPLOY_HOST:?Set DEPLOY_HOST=user@host (the VPS SSH target)}"

# Derive the build-time endpoints from DOMAIN unless the caller pinned them. This
# keeps the compiled origins in lockstep with the Caddyfile CSP connect-src.
export VITE_API_URL="${VITE_API_URL:-https://api.$DOMAIN}"
export VITE_REALTIME_URL="${VITE_REALTIME_URL:-wss://ws.$DOMAIN}"
export VITE_LIVEKIT_URL="${VITE_LIVEKIT_URL:-wss://livekit.$DOMAIN}"
if [[ -z "${VITE_APP_VERSION:-}" ]]; then
  VITE_APP_VERSION="$(sed -n 's/.*"version"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' \
    "$REPO_ROOT/apps/web/package.json" | head -1)"
  export VITE_APP_VERSION
fi

if [[ "${SKIP_BUILD:-0}" != "1" ]]; then
  echo "== Building @demli/web =="
  echo "   VITE_API_URL=$VITE_API_URL"
  echo "   VITE_REALTIME_URL=$VITE_REALTIME_URL"
  echo "   VITE_LIVEKIT_URL=$VITE_LIVEKIT_URL"
  echo "   VITE_APP_VERSION=$VITE_APP_VERSION"
  ( cd "$REPO_ROOT" && pnpm --filter @demli/web build )
fi

if [[ ! -f "$DIST_DIR/index.html" ]]; then
  echo "MISSING: $DIST_DIR/index.html — build did not produce a dist (run without SKIP_BUILD)." >&2
  exit 1
fi

echo "== Publishing web → $DEPLOY_HOST:$REMOTE_DIR =="
printf '  %-28s %s bytes\n' "index.html" "$(wc -c < "$DIST_DIR/index.html")"
[[ -d "$DIST_DIR/assets" ]] && printf '  %-28s %s files\n' "assets/" "$(find "$DIST_DIR/assets" -type f | wc -l)"

# Upload from inside dist/ with RELATIVE names — the native Windows pscp.exe does
# not understand MSYS "/c/…" source paths. `-r` recurses into assets/. Files land
# in place, merging with (and overwriting) the existing tree.
cd "$DIST_DIR"

if [[ -n "${DEPLOY_PASS:-}" ]] && command -v pscp >/dev/null 2>&1; then
  echo "== auth: PuTTY pscp (password, pinned host key) =="
  remote_putty_pw_args pscp
  if command -v plink >/dev/null 2>&1; then
    plink "${REMOTE_PUTTY_ARGS[@]}" "$DEPLOY_HOST" "install -d '$REMOTE_DIR'" || true
  fi
  pscp -r "${REMOTE_PUTTY_ARGS[@]}" * "$DEPLOY_HOST:$REMOTE_DIR/"
elif [[ -n "${DEPLOY_PASS:-}" ]] && command -v sshpass >/dev/null 2>&1; then
  echo "== auth: sshpass scp (password, pinned host key) =="
  remote_scp_opts
  remote_password_env
  sshpass -e ssh "${REMOTE_SSH_OPTS[@]}" "$DEPLOY_HOST" "install -d '$REMOTE_DIR'"
  sshpass -e scp -r "${REMOTE_SCP_OPTS[@]}" * "$DEPLOY_HOST:$REMOTE_DIR/"
elif [[ -n "${DEPLOY_PASS:-}" ]]; then
  echo "DEPLOY_PASS set but neither 'pscp' (PuTTY) nor 'sshpass' is installed." >&2
  echo "Install PuTTY, or use SSH key auth (omit DEPLOY_PASS)." >&2
  exit 1
else
  echo "== auth: SSH key/agent (pinned host key) =="
  remote_scp_opts
  ssh "${REMOTE_SSH_OPTS[@]}" "$DEPLOY_HOST" "install -d '$REMOTE_DIR'"
  scp -r "${REMOTE_SCP_OPTS[@]}" * "$DEPLOY_HOST:$REMOTE_DIR/"
fi

echo "== Verifying https://app.$DOMAIN =="
# -I HEAD first (status line), then confirm the SPA root actually serves.
curl -fsS -I "https://app.$DOMAIN" | sed -n '1,6p'
if curl -fsS "https://app.$DOMAIN" | grep -q 'id="root"'; then
  echo "OK — web live at https://app.$DOMAIN"
else
  echo "WARN: served response did not contain the app root div — check the deploy." >&2
  exit 1
fi
